"""Self-contained audit atlas and design sketches; never screenshots of gameplay."""
import base64, json, math
from pathlib import Path
from PIL import Image, ImageDraw
from geometry import read, write
from audit import NAMES

def data_image(path):return 'data:image/png;base64,'+base64.b64encode(Path(path).read_bytes()).decode()
def sketches(output):
    out=[]
    for i,title in enumerate(['Grota z szerokimi komorami','Ruiny z alternatywnymi trasami','Labirynt z arenami']):
        im=Image.new('RGB',(720,420),'#0d1e2b');d=ImageDraw.Draw(im);floor='#426673';edge='#739795'
        if i==0:
            for box in [(35,105,310,350),(210,35,525,295),(430,140,690,390)]:d.ellipse(box,fill=floor,outline=edge,width=3)
            d.ellipse((275,108,347,170),fill='#1b415b');d.ellipse((120,190,165,250),fill='#192d35')
        elif i==1:
            d.line([(105,115),(360,115),(600,115),(600,305),(360,305),(105,305),(105,115)],fill=floor,width=54)
            d.line([(360,115),(360,305)],fill=floor,width=54)
            for x,y in [(105,115),(360,115),(600,115),(105,305),(360,305),(600,305)]:d.rectangle((x-65,y-60,x+65,y+60),fill=floor,outline=edge,width=3)
        else:
            d.line([(70,210),(70,65),(280,65),(280,330),(480,330),(480,100),(650,100),(650,330)],fill=floor,width=46)
            d.line([(280,210),(480,210)],fill=floor,width=46)
            for x,y in [(70,210),(280,330),(480,100),(650,330)]:d.ellipse((x-48,y-48,x+48,y+48),fill=floor,outline=edge,width=2)
        d.ellipse((62,200,82,220),fill='#91dab2');d.ellipse((594,294,624,324),fill='#e5b369')
        d.text((20,14),title,fill='#edf4f1');d.text((20,392),'KONCEPCJA · nie jest aktywnym wnętrzem ani dowodem gry',fill='#c8d1d5')
        path=output/f'interior-concept-{i+1}.png';im.save(path);out.append((title,path))
    return out

def present(output):
    report=read(output/'audit.json');proposal=read(output/'dungeon-proposal.json');index=read(output/'index.json');overview=read(output/'overview.json')
    concepts=sketches(output)
    towns={k:v for k,v in index['planet']['features'].items()if v['kind']=='continent'}
    cards=''.join(f'<article class="land"><h3>{NAMES.get(f["feature"],"Wyspa "+f["feature"].split("-")[-1])}</h3><img alt="Mapa {f["feature"]}" src="{data_image(output/f["feature"]/"map.png")}"><p>{f["width"]:,} × {f["height"]:,} j. · siatka projektu 128 j.</p></article>'for f in index['features'])
    rows=''.join(f'<tr><td>{e["id"]}</td><td>{e["theme"]}</td><td>{"labirynt"if e["labyrinth"]else"przejście"if e["type"]=="transit"else"otwarte komory"}</td><td>{e["sizeProposal"][0]} × {e["sizeProposal"][1]}</td><td>{e["passageWidthMin"]} j.</td></tr>'for e in proposal['entries'])
    entrances=''.join(f'<tr><td>{e["id"]}</td><td>{p["feature"]}</td><td>{p["planet"]["lon"]:.4f}°, {p["planet"]["lat"]:.4f}°</td><td>{p["reuseCandidate"]}</td></tr>'for e in proposal['entries']for p in e['entrances'])
    sketch_cards=''.join(f'<figure><img src="{data_image(p)}" alt="{title}"><figcaption>{title} · projekt proporcji przestrzeni</figcaption></figure>'for title,p in concepts)
    markers=''.join(f'<g transform="translate({(f["lon"]+180)/360*1000},{(90-f["lat"])/180*500})"><circle r="3"/><text x="7" y="-7">{NAMES[k]}</text></g>'for k,f in towns.items())
    html='''<!doctype html><html lang="pl"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Superior — audyt geometrii v2</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#091722;color:#e5eee9;font:15px/1.6 system-ui,sans-serif}main{max-width:1500px;margin:auto;padding:48px 40px}header{border-bottom:1px solid #304450;padding-bottom:25px;display:flex;justify-content:space-between;gap:30px}h1{font-size:66px;line-height:1;margin:10px 0 18px;letter-spacing:.06em;font-weight:500}h2{font-size:30px;font-weight:500;margin:50px 0 16px}h3{font-size:20px;margin:12px 0}.eyebrow{letter-spacing:.22em;text-transform:uppercase;color:#bbcaab;font-size:12px}.muted,p,figcaption{color:#a9bdc5}.badge{display:inline-block;border:1px solid #9c8250;color:#ecd7a0;padding:7px 15px;border-radius:4px;font-size:12px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:18px;margin:30px 0}.stat,.land{background:#102431;border:1px solid #2a424d;padding:22px;border-radius:8px}.stat b{display:block;font-size:40px;font-weight:500;color:#f0e3b8}.maprow{display:grid;grid-template-columns:1fr 1fr;gap:22px}figure{margin:0;background:#102431;border:1px solid #2c4450;border-radius:8px;overflow:hidden}figcaption{padding:12px 18px}.map{position:relative}.map img{display:block;width:100%}.map svg{position:absolute;inset:0;width:100%;height:100%;fill:#ffe5a7;font:16px system-ui;text-shadow:0 1px 5px #000}.legend{display:flex;flex-wrap:wrap;gap:22px;margin:18px 0}.swatch{display:inline-block;width:12px;height:12px;border-radius:50%;margin-right:7px}.globeRow{display:grid;grid-template-columns:430px 1fr;gap:40px;align-items:center}.globeRow canvas{max-width:100%;touch-action:none;cursor:grab}button,select{font:inherit;background:#193442;color:#f0e6bf;border:1px solid #59717b;border-radius:4px;padding:8px 16px}input{width:100%;accent-color:#d9c38c}.lands{display:grid;grid-template-columns:repeat(2,1fr);gap:24px}.land img{width:100%;max-height:470px;object-fit:contain;background:#102a40}.graph{max-width:850px;width:100%;display:block;margin:auto}.graph text{fill:#e5eee9;font:18px system-ui}.graph .node{fill:#173745;stroke:#718e95}.graph .link{fill:none;stroke:#d2bb82;stroke-width:3;stroke-dasharray:8 6}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:12px;border-bottom:1px solid #263e4b}th{color:#e5d3a3}details{margin:24px 0}summary{cursor:pointer;color:#e5d3a3}.concepts{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.concepts img{width:100%}.note{border-left:3px solid #c3ab73;padding:10px 20px;background:#122633}.pair{display:grid;grid-template-columns:1fr 1fr;gap:24px}a{color:#daca9d}footer{border-top:1px solid #304450;margin-top:45px;padding-top:20px;color:#9db3bd;font-size:12px}@media(max-width:800px){main{padding:24px 18px}h1{font-size:44px}.stats{grid-template-columns:1fr 1fr}.maprow,.lands,.pair,.concepts,.globeRow{grid-template-columns:1fr}header{display:block}.globeRow canvas{margin:auto}h2{font-size:25px}}@media print{body{background:white;color:#172833}main{padding:12px}p,figcaption{color:#344b58}button,input,select{display:none}.stat,.land,figure,.note{background:#f0f4f5;color:#123}.stat b{color:#163d45}h2{break-after:avoid}.land,figure,table{break-inside:avoid}details{display:none}}
</style><main><header><div><div class="eyebrow">KI Legends · projekt Architekta · 24.10.2026</div><h1>SUPERIOR</h1><p>Nowa geografia. Te same cztery kontynenty. Sześć zachowanych wysp.</p></div><div><span class="badge">ETAP A + PROTOTYP B · DO AUDYTU</span><p>Geometria sferyczna · CPU<br>Bez scalenia i bez publikacji</p></div></header>
<div class="stats"><div class="stat">Lądy — obrys kontynentalny<b>LAND%</b>cel 45% ±0,5 pp</div><div class="stat">Oceany<b>OCEAN%</b>cel 55% ±0,5 pp</div><div class="stat">Docelowe podziemia<b>18 / 20</b>projekt, nie aktywne lokacje</div><div class="stat">Labirynty<b>4 / 5</b>14 otwartych kompleksów</div></div>
<h2>Przed i po przebudowie</h2><p>Ta sama projekcja równokątna 2:1. Procenty liczymy na sferze — piksele przy biegunach mają znacznie mniejszą powierzchnię niż przy równiku.</p>
<div class="maprow"><figure><div class="map"><img src="BEFORE" alt="Superior przed zmianą"><svg viewBox="0 0 1000 500">MARKERS</svg></div><figcaption>V1 · BEFOREPC% lądu · źródłowa geometria gry</figcaption></figure><figure><div class="map"><img src="AFTER" alt="Superior po zmianie"><svg viewBox="0 0 1000 500">MARKERS</svg></div><figcaption>V2 · LAND% lądu · złota linia: stare wybrzeże</figcaption></figure></div>
<div class="legend"><span><i class="swatch" style="background:#4d996a"></i>Verdantia · Planetarni</span><span><i class="swatch" style="background:#87bac9"></i>Aetheria · Mędrcy</span><span><i class="swatch" style="background:#7683b4"></i>Nexus-9 · Androidy</span><span><i class="swatch" style="background:#cc7453"></i>Pyra · Legendy</span><span><i class="swatch" style="background:#d2ae72"></i>Wyspy I–VI</span></div>
<div class="globeRow"><canvas id="globe" width="420" height="420" aria-label="Obracany globus prototypu"></canvas><div><h2>Sprawdź planetę na sferze</h2><p>Przeciągnij globus lub zmień długość geograficzną. Ten podgląd czyta ten sam obrys co atlas 2D. Przecięcie szwu mapy nie rozcina kontynentu w świecie.</p><label>Wersja <select id="version"><option value="after">V2 — prototyp</option><option value="before">V1 — dotychczasowa</option></select></label><p><label>Długość środka widoku <input id="longitude" type="range" min="-180" max="180" value="-29"></label></p><p class="muted">To przeglądarka danych geograficznych, nie uruchomiona scena Phaser.</p></div></div>
<h2>Dziesięć lądów — szkic terenu i dróg</h2><p>Zachowano miasta i NPC. Kolory przedstawiają robocze biomy; jasne linie — wyznaczone na nowej geometrii trasy do osad i kilku punktów eksploracji. To siatka 128 j., a nie końcowa nawigacja postaci 16 j.</p><div class="lands">CARDS</div>
<h2>Podziemna sieć kontynentów</h2><p>Cztery dwukierunkowe połączenia tworzą cykl. Każdy kontynent ma dwie drogi do sieci. Linie oznaczają połączenia logiczne, nie zatwierdzone tunele pod oceanem.</p>
<svg class="graph" viewBox="0 0 850 330" role="img" aria-label="Graf: Verdantia — Aetheria — Nexus-9 — Pyra — Verdantia"><path class="link" d="M180 80H670V250H180Z"/><rect class="node" x="80" y="45" width="200" height="70" rx="12"/><rect class="node" x="570" y="45" width="200" height="70" rx="12"/><rect class="node" x="570" y="215" width="200" height="70" rx="12"/><rect class="node" x="80" y="215" width="200" height="70" rx="12"/><text x="135" y="87">Verdantia</text><text x="625" y="87">Aetheria</text><text x="625" y="257">Nexus-9</text><text x="155" y="257">Pyra</text><text x="365" y="65">Przejście 1</text><text x="685" y="170">2</text><text x="365" y="275">Przejście 3</text><text x="150" y="170">4</text></svg>
<div class="pair"><div class="note"><h3>Rekomendacja: powiązane instancje</h3><p>Duże, zróżnicowane wnętrze ma portal wejściowy i wyjściowy. Zapis pamięta stronę wejścia i punkt powrotu. Telefon ładuje tylko aktywną lokację. Nie przesądza to fizycznej geologii pod oceanem.</p></div><div class="note"><h3>Alternatywa: ciągła przestrzeń</h3><p>Fizyczne przejścia mają odległości planetarne, wymagają podziemnego strumieniowania i większych map. Powodują znacznie dłuższe podróże i wymagają decyzji o kanonie geologicznym. Nie implementowano tej wersji.</p></div></div>
<h2>18 lokacji zamiast 152</h2><p>Robocze typy i identyfikatory, bez nadawania ostatecznych nazw fabularnych. Dwa miejsca w limicie pozostają wolne.</p><div class="scroll"><table><thead><tr><th>ID</th><th>Klimat</th><th>Typ</th><th>Rozmiar projektu</th><th>Min. przejście</th></tr></thead><tbody>ROWS</tbody></table></div><details><summary>Orientacyjne wejścia i wyjścia — współrzędne i pochodzenie</summary><div class="scroll"><table><tr><th>Lokacja</th><th>Ląd</th><th>Długość, szerokość</th><th>Kandydat z v1</th></tr>ENTRANCES</table></div></details>
<h2>Rozległa przestrzeń zamiast wąskich korytarzy</h2><div class="concepts">SKETCHES</div><p>Ilustracje układów do dyskusji. Nie są wygenerowanymi zasobami końcowymi ani screenshotami gry. Zielony punkt: wejście; złoty: obszar starcia. Docelowe przejścia 256–384 j., areny 768–1280 j. lub większe.</p>
<h2>Granica tego odbioru</h2><div class="pair"><div><h3>Wykonano</h3><ul><li>Pomiar sferyczny oraz niezależną całkę po wybrzeżu.</li><li>Nową geometrię dziesięciu lądów, biomy i robocze trasy.</li><li>Inwentaryzację 152 planów i odwołań.</li><li>Projekt 18 lokacji, czterech labiryntów i sieci przejść.</li><li>Próbę migracji współrzędnych bez zapisu do pamięci gracza.</li></ul></div><div><h3>Jeszcze nie wdrożono</h3><ul><li>Nowej planety w działającym Phaser i produkcyjnym globusie.</li><li>Grywalnych nowych podziemi oraz portali.</li><li>Końcowych spawnów, kolizji 16 j. i hydrologii.</li><li>Migracji prawdziwych zapisów i odbioru telefonu.</li></ul></div></div>
<div class="note"><p>45% dotyczy obrysu lądów, z jeziorami śródlądowymi. Ich zachowana powierzchnia v1 wynosi około 0,032% planety; także po odjęciu mieścimy się w tolerancji 44,5–45,5%. Rozbudowa jezior wymaga ponownego bilansu suchego lądu. Obecna gra nadal korzysta z nienaruszonego superior-v1. 152 starych wejść nie zostanie skopiowanych do aktywnego indeksu v2.</p></div>
<footer>KI LEGENDS · SUPERIOR V2 · RAPORT DO NIEZALEŻNEGO AUDYTU<br>Źródła i dokładne pomiary: audit.json · historical-dungeons.json · dungeon-proposal.json · migration-report.json · validation.json</footer></main>
<script>
const data=OVERVIEW;
const decode=r=>{let out=new Uint8Array(data.width*data.height),at=0;for(const [v,n]of r){out.fill(v,at,at+n);at+=n;}return out;};
const maps={before:decode(data.before),after:decode(data.after)},colors=data.colors.map(c=>[1,3,5].map(i=>parseInt(c.slice(i,i+2),16)));
const canvas=document.getElementById('globe'),ctx=canvas.getContext('2d'),longitude=document.getElementById('longitude'),version=document.getElementById('version');let lat=.25;
function draw(){const size=420,r=192,c=size/2,lo=Number(longitude.value)*Math.PI/180,im=ctx.createImageData(size,size),map=maps[version.value];for(let y=0;y<size;y++)for(let x=0;x<size;x++){let a=(x-c)/r,b=(c-y)/r,q=a*a+b*b;if(q>1)continue;let z=Math.sqrt(1-q),vy=b*Math.cos(lat)+z*Math.sin(lat),vx=a,vz=z*Math.cos(lat)-b*Math.sin(lat),lon=Math.atan2(vx,vz)+lo,la=Math.asin(Math.max(-1,Math.min(1,vy))),mx=((Math.floor((lon+Math.PI)/(2*Math.PI)*data.width)%data.width)+data.width)%data.width,my=Math.max(0,Math.min(data.height-1,Math.floor((Math.PI/2-la)/Math.PI*data.height))),col=colors[map[my*data.width+mx]],light=.55+.45*z,i=(y*size+x)*4;for(let k=0;k<3;k++)im.data[i+k]=col[k]*light;im.data[i+3]=255;}ctx.clearRect(0,0,size,size);ctx.putImageData(im,0,0);}
longitude.oninput=draw;version.onchange=draw;let drag=null;canvas.onpointerdown=e=>{drag=[e.clientX,e.clientY,Number(longitude.value),lat];canvas.setPointerCapture(e.pointerId)};canvas.onpointermove=e=>{if(!drag)return;longitude.value=String(Math.max(-180,Math.min(180,drag[2]-(e.clientX-drag[0])*.45)));lat=Math.max(-1.5,Math.min(1.5,drag[3]+(e.clientY-drag[1])*.006));draw()};canvas.onpointerup=()=>drag=null;canvas.onpointercancel=()=>drag=null;draw();document.documentElement.dataset.ready='true';
</script></html>'''
    replacements={'LAND':f'{report["landAfterPercent"]:.3f}','OCEAN':f'{report["oceanAfterPercent"]:.3f}','BEFOREPC':f'{report["landBeforePercent"]:.3f}', 'BEFORE':data_image(output/'before.png'),'AFTER':data_image(output/'after.png'),'MARKERS':markers,'CARDS':cards,'ROWS':rows,'ENTRANCES':entrances,'SKETCHES':sketch_cards,'OVERVIEW':json.dumps(overview,separators=(',',':'))}
    for a,b in replacements.items():html=html.replace(a,b)
    (output/'audit.html').write_text(html)

if __name__=='__main__':
    import sys
    present(Path(sys.argv[1]))
